# Blesi - Medical Assisting: Administrative & Clinical Competencies.
# Unit list: 9th edition, from the publisher's table of contents on cengage.com. The publisher page lists the book's
# 15 units (each unit holds several chapters), so summaries are organized by unit.
# Summaries cover each unit's standard topics; they are written for this site, not copied from the book.

C = [
    (1, "Introduction to Health Care", [
        "Medical assistants are multiskilled professionals who perform administrative and clinical tasks in ambulatory care settings. They can become certified (CMA through the AAMA, RMA through AMT, and others). Professionalism includes dependability, appearance, teamwork, and continuing education.",
        "This unit covers the history of medicine, health care settings and specialties, legal concepts (scope of practice, negligence, informed consent, HIPAA, licensure), ethics, and therapeutic communication: active listening, nonverbal cues, cultural awareness, and Maslow's hierarchy of needs.",
    ], ["CMA (AAMA) and RMA (AMT) credentials", "Stay within scope of practice", "HIPAA protects privacy", "Therapeutic communication and active listening"]),
    (2, "Anatomy and Physiology of the Human Body", [
        "Medical assistants need a working knowledge of anatomy, physiology, and medical terminology. The body is organized from cells to tissues, organs, and systems. Directional terms, body planes, and body cavities describe locations.",
        "Each body system (integumentary, skeletal, muscular, nervous, sensory, endocrine, circulatory, lymphatic and immune, respiratory, digestive, urinary, and reproductive) has structures, functions, and common diseases that medical assistants should recognize.",
    ], ["Cells → tissues → organs → systems", "Directional terms and body planes", "Each system: structure, function, disease", "Medical terminology is essential"]),
    (3, "Business Communications", [
        "The front office handles telephone communication, written correspondence, and patient reception. Telephone skills include answering promptly, identifying the office and yourself, screening and triaging calls, and taking complete messages.",
        "Written communication includes business letters (full block, modified block), memos, and emails using correct grammar and format. Technology such as practice management software, patient portals, and electronic communication must protect patient privacy.",
    ], ["Answer phones promptly and identify the office", "Triage calls by urgency", "Business letter formats", "Protect privacy in all communication"]),
    (4, "Beginning the Patient's Record", [
        "Scheduling methods include wave, modified wave, open hours, and time-specified (stream) scheduling. Patient registration collects demographics and insurance information. Reception duties include greeting patients and maintaining a welcoming, safe office.",
        "The medical record, paper or electronic (EHR), is a legal document. Records are organized using formats such as problem-oriented (POMR) and SOAP notes (Subjective, Objective, Assessment, Plan). Filing systems include alphabetical and numerical, and corrections must follow legal rules.",
    ], ["Wave and time-specified scheduling", "Medical record = legal document", "SOAP: Subjective, Objective, Assessment, Plan", "Correct errors properly; never erase"]),
    (5, "Medical Insurance and Coding", [
        "Health insurance includes private plans, managed care (HMOs, PPOs), Medicare, Medicaid, TRICARE, and workers' compensation. Terms include premium, deductible, co-payment, coinsurance, and preauthorization.",
        "Coding translates services and diagnoses into codes: CPT and HCPCS for procedures and services, and ICD-10-CM for diagnoses. Claims are usually submitted electronically on the CMS-1500 format. Accurate coding prevents denials and fraud.",
    ], ["Premium, deductible, co-pay, coinsurance", "CPT = procedures; ICD-10-CM = diagnoses", "CMS-1500 claim form", "Accurate coding prevents fraud"]),
    (6, "The Revenue Cycle", [
        "The revenue cycle covers everything from scheduling to final payment: verifying insurance, collecting co-pays, charge entry, claims submission, payment posting, and collections. Accounts receivable is money owed to the practice.",
        "Bookkeeping and banking include daily reconciliation, deposits, petty cash, accounts payable, and payroll basics. Collections must follow fair debt collection laws.",
    ], ["Revenue cycle: registration to payment", "Accounts receivable = money owed to the practice", "Collect co-pays at the visit", "Follow fair debt collection laws"]),
    (7, "Preparing for Clinical Procedures", [
        "Clinical work begins with infection control: medical asepsis, hand hygiene, standard precautions, PPE, sanitization, disinfection, and sterilization (autoclave). OSHA's Bloodborne Pathogens Standard protects workers.",
        "Medical assistants take patient histories, measure vital signs (temperature, pulse, respirations, blood pressure, oxygen saturation, pain), and measure height, weight, and BMI. Normal adult values include a pulse of 60–100 and respirations of 12–20.",
    ], ["Hand hygiene and standard precautions", "Autoclave sterilizes instruments", "Adult pulse 60–100; respirations 12–20", "Measure height, weight, and BMI"]),
    (8, "Assisting with Examinations", [
        "Medical assistants prepare exam rooms, position and drape patients, and assist providers. Exam positions include supine, prone, Sims', Fowler's, lithotomy, and knee-chest. Exam methods are inspection, palpation, percussion, and auscultation.",
        "This unit also covers specialty exams: pediatrics (growth charts, immunizations), OB/GYN (Pap tests), geriatrics, eye and ear exams (Snellen chart), and others. Patient education and documentation are part of every exam.",
    ], ["Inspection, palpation, percussion, auscultation", "Lithotomy for pelvic exams; Sims' for rectal", "Snellen chart tests distance vision", "Growth charts and immunizations for children"]),
    (9, "Laboratory Procedures", [
        "Medical assistants perform CLIA-waived tests and collect specimens. Lab safety, quality control, and proper specimen handling are essential. Using the microscope and following the order of draw are core skills.",
        "Procedures include venipuncture and capillary puncture, hematology tests (hemoglobin, hematocrit), urinalysis, blood glucose, and microbiology specimens such as throat cultures and rapid strep tests.",
    ], ["CLIA-waived tests", "Order of draw for blood tubes", "Capillary puncture and venipuncture", "Rapid strep and throat cultures"]),
    (10, "Cardiology and Radiology Procedures", [
        "An electrocardiogram (ECG/EKG) records the heart's electrical activity using 12 leads from 10 electrodes. Medical assistants prepare the patient, place electrodes correctly, recognize artifacts, and identify basic rhythms. Related tests include Holter monitoring and stress tests.",
        "Radiology procedures include X-rays, CT, MRI, ultrasound, and mammography. Medical assistants prepare and educate patients and follow radiation safety rules (time, distance, shielding).",
    ], ["12-lead ECG uses 10 electrodes", "Holter monitor records 24–48 hours", "MRI uses magnets; X-ray uses radiation", "Radiation safety: time, distance, shielding"]),
    (11, "Minor Surgical Procedures", [
        "Medical assistants assist with minor office surgeries such as suturing, removal of skin lesions, and incision and drainage. Surgical asepsis (sterile technique) is required: setting up a sterile field, opening sterile packs, and sterile gloving.",
        "Instruments include scalpels, scissors, forceps, hemostats, and needle holders. Wound care includes dressing changes, suture and staple removal, and patient education about signs of infection.",
    ], ["Surgical asepsis = sterile technique", "Never reach across a sterile field", "Hemostats clamp vessels", "Teach signs of infection"]),
    (12, "Medication Administration Procedures", [
        "Pharmacology basics include drug names (generic and brand), drug classes, schedules of controlled substances (DEA Schedules I–V), and reading prescriptions. Dosage calculations use formulas such as desired over have times quantity.",
        "The rights of medication administration include right patient, drug, dose, route, time, and documentation. Routes include oral, sublingual, topical, inhalation, and injections: intradermal (ID), subcutaneous (subcut), and intramuscular (IM). Injection sites include the deltoid, vastus lateralis, and ventrogluteal.",
    ], ["Rights of medication administration", "Controlled substance schedules I–V", "ID, subcut, IM injections", "Deltoid, vastus lateralis, ventrogluteal sites"]),
    (13, "First Aid and Responding to Emergencies", [
        "Medical assistants must be ready for office emergencies: maintaining an emergency crash cart, performing CPR and using an AED, and calling EMS. Common emergencies include fainting (syncope), seizures, shock, allergic reactions and anaphylaxis, diabetic emergencies, and heart attack and stroke.",
        "First aid also covers bleeding control, burns, fractures, sprains, poisoning, and heat and cold injuries. Documentation and staying within scope of practice are important.",
    ], ["Keep the crash cart stocked", "CPR and AED", "Anaphylaxis requires epinephrine", "Syncope = fainting"]),
    (14, "Rehabilitation and Healthy Living", [
        "Rehabilitation helps patients regain function through physical and occupational therapy, assistive devices (canes, crutches, walkers, wheelchairs), and heat and cold therapy. Medical assistants teach proper use of devices and body mechanics.",
        "Healthy living includes nutrition, exercise, weight management, stress reduction, and avoiding tobacco and substance abuse. Patient education promotes wellness and disease prevention.",
    ], ["Assistive devices: canes, crutches, walkers", "Heat increases circulation; cold reduces swelling", "Teach healthy habits", "Prevention reduces disease"]),
    (15, "Workplace Readiness", [
        "Preparing for employment includes the practicum (externship), building a résumé and cover letter, interviewing, and earning certification. Professional behavior during the externship can lead to job offers.",
        "Career success depends on teamwork, time management, professionalism, and continuing education to maintain credentials.",
    ], ["Externship = on-the-job training", "Résumé and cover letter", "Certification improves job prospects", "Continuing education maintains credentials"]),
]

